vector<vector<int>> fourSum(vector<int>& nums, int target) {
    int n = (int)nums.size();
    set<vector<int>> found;
    for (int i = 0; i < n; i++) {                                // every combination of 4 indices is checked
        for (int j = i + 1; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
