import java.util.*;

public class Main {
    List<List<Integer>> fourSum(int[] nums, int target) {
        Arrays.sort(nums);
        int n = nums.length;
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n - 3; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;               // skip a duplicate first value
            for (int j = i + 1; j < n - 2; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue;         // skip a duplicate second value
                int left = j + 1, right = n - 1;
                long remaining = (long) target - nums[i] - nums[j];
                while (left < right) {
                    long total = (long) nums[left] + nums[right];
                    if (total == remaining) {
                        result.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));
                        left++;
                        right--;
                        while (left < right && nums[left] == nums[left - 1]) left++;      // skip a duplicate left value
                        while (left < right && nums[right] == nums[right + 1]) right--;    // skip a duplicate right value
                    } else if (total < remaining) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        return result;
    }

